import{_ as s,l as r,o as e,c as n,v as o,p as d,x as t,d as i,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"TLB shootdown","description":"","frontmatter":{"title":"TLB shootdown","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tlb-shootdown.md","filePath":"cs/tlb-shootdown.md","lastUpdated":1789023840000}'),c={name:"cs/tlb-shootdown.md"};function m(P,a,T,I,A,_){const l=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="tlb-shootdown" tabindex="-1">TLB shootdown <a class="header-anchor" href="#tlb-shootdown" aria-label="Permalink to &quot;TLB shootdown&quot;">​</a></h1><div class="epigraph"><p>页表改了只保证本 CPU 看见新翻译；其他核的 TLB 仍可能缓存旧的 VPN→PPN，必须显式作废。</p><footer>—— 据 Black et al. 对 MACH 多处理器 TLB 一致性的讨论；Love, Linux Kernel Development 整理</footer></div><p><a href="/cs/huge-pages">上一课</a>让一条 TLB 项覆盖更大块。<a href="/cs/tlb-translate">TLB</a> 是每核私有的旁视缓冲，不是共享页表本身。<a href="/cs/page-fault-path">缺页路径</a>在本 CPU 填表并局部冲 TLB。缺口是<strong>多核</strong>：解映射、改权限、拆大页之后，别的核若仍用旧项，会写出已不属于该进程的物理页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>页表在内存里，改 PTE 对所有核「最终」可见，但 TLB 是各核 SRAM 副本。没有总线嗅探来自动丢翻译项。缺口不是再讲 ASID，而是：发起核发出核间中断（IPI），请其他核执行 <code>invlpg</code> 或冲本进程的一组项，并等待它们做完——这叫 shootdown。范围过大则变成全核风暴；过小则漏冲。</p><p>本课不把每种 ISA 的 INVLPG 编码写完。</p><p><span class="marginnote">惰性 shootdown：记下「世代」，核回到该进程时再冲。降低 IPI，换来短暂的过期翻译窗口，必须与 ASID/PCID 或「该页已不可写」等约束搭配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>解映射：锁页表，清有效位，对本 CPU 冲 TLB，向持有该 mm 的 CPU 集发 IPI。各核在中断里冲指定 VA 或整张用户 TLB，应答。发起者等到齐再复用物理帧——否则 DMA 或别核 store 仍打旧帧。大页 shootdown 按大页基址作废。</p>',9)),(e(),d(p,null,{default:t(()=>[h(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNMAP%5B%22%E6%B8%85%20PTE%22%5D%20--%3E%20IPI%5B%22IPI%20%E9%80%9A%E7%9F%A5%E6%8C%81%E6%9C%89%E8%AF%A5%20mm%20%E7%9A%84%E6%A0%B8%22%5D%0A%20%20IPI%20--%3E%20INV%5B%22%E5%90%84%E6%A0%B8%20invlpg%20%2F%20%E5%86%B2%20ASID%22%5D%0A%20%20INV%20--%3E%20WAIT%5B%22%E7%AD%89%E9%BD%90%E5%90%8E%E5%86%8D%E5%A4%8D%E7%94%A8%E5%B8%A7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>shootdown 把 <a href="/cs/tlb-translate">TLB</a> 从「单核加速」接到「多核正确性」：它是虚存的一致性协议，对象是翻译，不是数据 Cache 行（数据一致性仍走 MESI 课）。频繁 <code>mprotect</code>、munmap、大页拆分会让 IPI 成为可测的开销，于是有范围聚合与惰性策略。</p><p>不要把页表 walker 再推一遍：walker 读的是内存中的新 PTE；错误来自旁路缓冲。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 x86 PCID 与 INVPCID 的全部优化表。不把 GPU 的自己的 TLB 写进主干。内核映射全局项（用户/内核分裂里的高半）改动更危险，通常极少改或用专门全局冲。下一课假设：帧要被抢走时，翻译已经到处作废。</p><p>后课默认：解映射在多核上可完成。无空闲帧时淘汰谁、如何选牺牲页，下一课缺页与置换。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>改 PTE 后必须 shootdown 他核 TLB，才能复用帧。</li><li>IPI 是开销；惰性与范围聚合是实现。</li><li>无帧时的淘汰算法是置换课的缺口。</li><li>出处：Black et al. 对 MACH TLB；Love, <em>LKD</em>；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const u=s(c,[["render",m]]);export{E as __pageData,u as default};
